#pragma once

// Recovered Thumb argument producers from every bundled S/X release record.
// Each band includes its native incremental erase/update paths. Top/bottom
// margins resize with opposite signs; UID row advances and history bar heights
// remain native computations, rather than being flattened to host constants.
struct PageCoordinate {
    uint32_t address;
    Encoding encoding;
    int value;
    bool vertical;
    int scale, minimum;
};
struct PageGuard { uint32_t address; size_t length; };
struct PageDescription {
    uint32_t screen;
    int x0, y0, x1, y1;
    size_t firstSite, siteCount, firstGuard, guardCount;
    std::array<uint32_t, 4> phase;
};
struct PageRecord {
    size_t edition;
    uint16_t code;
    uint32_t base, stack;
    size_t firstPage, pageCount;
};

